import unittest
import dispatch_scan as app

class Behavior(unittest.TestCase):
    def test_line_endings(self):
        self.assertEqual(app.scan_codes('BX7\nQ9'), ['BX7', 'Q9'])
        self.assertEqual(app.scan_codes('BX7\r\nQ9\r\n'), ['BX7', 'Q9'])
        self.assertEqual(app.scan_codes('A\r\nB\nC'), ['A', 'B', 'C'])
    def test_blank_and_preserved_spaces(self):
        self.assertEqual(app.scan_codes('\r\n\nA\n\n'), ['A'])
        self.assertEqual(app.scan_codes(' A \n \nZ'), [' A ', ' ', 'Z'])
        self.assertEqual(app.scan_codes(''), [])
        self.assertEqual(app.scan_codes('X'), ['X'])

    def test_additional_behavior(self):
        self.assertEqual(app.scan_codes(' N7 \r\n\r\nQ'), [' N7 ', 'Q'])

if __name__ == '__main__':
    unittest.main()
